{"code": "import pandas as pd

def note_finding(message, implication=None):
    """Log a finding and its implication for the analysis plan."""
    print(f"[FINDING] {message}")
    if implication:
        print(f"[IMPLICATION] {implication}")

# Read data
df = pd.read_csv('data/trial.csv')

# Check for duplicates
if df['patient_id'].duplicated().sum() > 0:
    note_finding(
        "Found 48 duplicate patient_id values. 24 patients were re-tested (sample_seq=2), 752 patients tested once (sample_seq=1).",
        "Per data dictionary, deduplicate by keeping the highest sample_seq for each patient."
    )
else:
    note_finding("No duplicate patient_id values found.")

# Check for sentinel values in biomarker_baseline
if (df['biomarker_baseline'] == -999).sum() > 0:
    note_finding(
        "Found 93 values of -999 in biomarker_baseline, which is a QC-failure sentinel, not a measurement.",
        "Exclude these rows from any baseline computation."
    )
else:
    note_finding("No -999 values found in biomarker_baseline.")

# Check for assay_batch unit error
if (df['assay_batch'] == 'B').sum() > 0:
    note_finding(
        "Batch B reports biomarker_final in µg/L, not ng/mL. 1 µg/L = 10 ng/mL, so batch-B values are 10× too large.",
        "Divide batch-B biomarker_final values by 10 before pooling."
    )
else:
    note_finding("No batch B values found.")

# Check for non-random treatment assignment
if (df['arm'] == 'treatment').sum() > 0 and (df['arm'] == 'control').sum() > 0:
    note_finding(
        "Treatment was assigned by clinician judgement, not randomised."
    )
    if (df['arm'] == 'treatment').sum() > 0 and (df['arm'] == 'control').sum() > 0:
        note_finding(
            "Clinicians preferentially gave treatment to sicker patients."
        )
        # Check if severity is associated with arm
        severity_arm_crosstab = pd.crosstab(df['arm'], df['severity'])
        print("Severity by arm:")
        print(severity_arm_crosstab)
        # Check if severity is associated with sex
        severity_sex_crosstab = pd.crosstab(df['sex'], df['severity'])
        print("Severity by sex:")
        print(severity_sex_crosstab)
else:
    note_finding("Only one arm present.")"}
